# ruff: noqa: I001, E401, E402, E701, E702, E731, F401, F811
# fmt: off
from __future__ import annotations; import json; import pytest; from truealpha_runtime.testing import OtlpCollectorStub, run_python_probe; IAC_REF = "0123456789abcdef0123456789abcdef01234567"; IDENTITY = { "deployment.environment.name": "staging", "infra.service.id": "truealpha/app", "service.version": "v1.2.3", "infra.iac.ref": IAC_REF, }
def _attributes(deployment_environment: str) -> str: issued = {**IDENTITY, "deployment.environment.name": deployment_environment}; return ",".join(f"{key}={value}" for key, value in issued.items())
DEPLOYED = { "OTEL_SERVICE_NAME": "truealpha-app", "APP_ENV": "staging", "OTEL_RESOURCE_ATTRIBUTES": _attributes(IDENTITY["deployment.environment.name"]), }; STATE_PROBE = '\nimport json, logging\nfrom llm_service import main\nfrom opentelemetry import trace\n\nprovider = trace.get_tracer_provider()\nresource = getattr(provider, "resource", None)\nprint(json.dumps({\n    "instrumented": bool(getattr(main.app, "_is_instrumented_by_opentelemetry", False)),\n    "sdk_provider": hasattr(provider, "resource"),\n    "service_name": resource.attributes.get("service.name") if resource else None,\n    "otlp_log_handlers": sum(\n        type(h).__name__ == "LoggingHandler" and type(h).__module__.startswith("opentelemetry")\n        for h in logging.getLogger().handlers\n    ),\n}))\n'
EXPORT_PROBE = '\nimport logging\nfrom fastapi.testclient import TestClient\nfrom llm_service import main\nfrom opentelemetry import _logs, metrics, trace\n\n# /mcp answers 307 from the app\'s own route: a real request through the instrumented stack that\n# needs no database.\nassert TestClient(main.app, follow_redirects=False).get("/mcp").status_code == 307\nlogging.getLogger("llm_service.probe").error("llm-service probe failure")\ntrace.get_tracer_provider().force_flush()\nmetrics.get_meter_provider().force_flush()\n_logs.get_logger_provider().force_flush()\n'
def test_without_an_endpoint_the_app_imports_with_telemetry_off() -> None: result = run_python_probe(STATE_PROBE, {}); assert result.returncode == 0, result.stderr; assert json.loads(result.stdout.splitlines()[-1]) == { "instrumented": False, "sdk_provider": False, "service_name": None, "otlp_log_handlers": 0, }
@pytest.mark.parametrize("deployment_environment", ["staging", "pr-12", "branch-main", "canary-preview"])
def test_with_an_endpoint_and_the_rendered_identity_the_app_is_instrumented(deployment_environment: str) -> None: environ = { **DEPLOYED, "APP_ENV": "staging", "OTEL_RESOURCE_ATTRIBUTES": _attributes(deployment_environment), "OTEL_EXPORTER_OTLP_ENDPOINT": "http://127.0.0.1:9", }; result = run_python_probe(STATE_PROBE, environ); assert result.returncode == 0, result.stderr; state = json.loads(result.stdout.splitlines()[-1]); assert state == { "instrumented": True, "sdk_provider": True, "service_name": "truealpha-app", "otlp_log_handlers": 1, }
@pytest.mark.parametrize("missing", ["OTEL_SERVICE_NAME", "OTEL_RESOURCE_ATTRIBUTES"])
def test_with_an_endpoint_but_without_the_identity_the_app_refuses_to_import(missing: str) -> None: environ = {key: value for key, value in DEPLOYED.items() if key != missing}; result = run_python_probe(STATE_PROBE, {**environ, "OTEL_EXPORTER_OTLP_ENDPOINT": "http://127.0.0.1:9"}); assert result.returncode != 0, "the service started and would have exported untagged telemetry"; assert "TelemetryConfigError" in result.stderr; assert missing in result.stderr; assert IAC_REF not in result.stderr, "names only, never values"
def test_a_request_and_an_error_log_reach_the_collector_under_the_rendered_identity() -> None:
    preview = {**DEPLOYED, "APP_ENV": "staging", "OTEL_RESOURCE_ATTRIBUTES": _attributes("pr-12")}
    with OtlpCollectorStub() as collector: result = run_python_probe(EXPORT_PROBE, {**preview, "OTEL_EXPORTER_OTLP_ENDPOINT": collector.endpoint})
    assert result.returncode == 0, result.stderr; assert any("/mcp" in name for name in collector.span_names()), collector.span_names(); assert "llm-service probe failure" in collector.log_bodies(); expected = {**IDENTITY, "deployment.environment.name": "pr-12", "service.name": "truealpha-app"}
    for signal in ("traces", "metrics", "logs"):
        resources = collector.resources(signal); assert resources, f"no {signal} reached the collector"
        for attributes in resources:
            for key, value in expected.items(): assert attributes.get(key) == value, f"{signal}: {key} is {attributes.get(key)!r}"
